// Parse Evolution API MESSAGES_UPSERT payload
const body = $json.body || $json;

// Ignore events that are not incoming messages
if (body.event && String(body.event).toLowerCase() !== 'messages.upsert') {
  return [];
}

const data = body.data || {};
const key = data.key || {};
const remoteJid = key.remoteJid || '';

// Ignore own messages, groups and status broadcasts
if (key.fromMe || !remoteJid || remoteJid.endsWith('@g.us') || remoteJid === 'status@broadcast') {
  return [];
}

const msg = data.message || {};
const rawText = msg.conversation || (msg.extendedTextMessage && msg.extendedTextMessage.text) || '';
if (!rawText.trim()) {
  return [];
}

return [{ json: {
  phone: remoteJid.split('@')[0],
  pushName: data.pushName || 'Cliente',
  rawText: rawText.trim(),
  text: rawText.toLowerCase().trim()
} }];

// Conversation state machine backed by Supabase.
// Config comes from n8n environment (see docker-compose.yml) — no secrets in this file.
const SUPABASE_URL = $env.SUPABASE_URL;
const SUPABASE_KEY = $env.SUPABASE_SERVICE_ROLE_KEY;

const http = this.helpers.httpRequest.bind(this.helpers);
const baseHeaders = {
  'apikey': SUPABASE_KEY,
  'Authorization': 'Bearer ' + SUPABASE_KEY,
  'Content-Type': 'application/json'
};

const sb = (method, path, body, prefer) => http({
  method,
  url: SUPABASE_URL + '/rest/v1/' + path,
  headers: prefer ? { ...baseHeaders, 'Prefer': prefer } : baseHeaders,
  body: body ? JSON.stringify(body) : undefined
});

const { phone, pushName, text, rawText } = $json;

const saveState = (state, data) => sb(
  'POST',
  'conversation_state?on_conflict=phone',
  { phone, state, data, updated_at: new Date().toISOString() },
  'resolution=merge-duplicates'
);

const menuText = (products) => {
  const rows = products
    .map((p, i) => (i + 1) + '. ' + (p.emoji || '🍲') + ' *' + p.name + '* - $' + p.price)
    .join('\n');
  return 'Bowls disponibles:\n\n' + rows + '\n\nEscribe el *número* del bowl que quieras.';
};

let reply;

try {
  const stateRows = await sb('GET', 'conversation_state?select=*&phone=eq.' + encodeURIComponent(phone));
  let state = stateRows[0] ? stateRows[0].state : 'idle';
  let data = (stateRows[0] && stateRows[0].data) || {};

  const createOrder = async (address, modeNote) => {
    try {
      await sb('POST', 'customers?on_conflict=phone',
        { phone, name: pushName, address },
        'resolution=merge-duplicates');
    } catch (e) {
      // customers table may not exist — the order itself carries the data
    }
    const orders = await sb('POST', 'orders', {
      customer_name: pushName,
      customer_phone: phone,
      customer_address: address,
      status: 'pending',
      total: data.bowl.price,
      notes: modeNote + ' - ' + data.bowl.name
    }, 'return=representation');
    await sb('POST', 'order_items', {
      order_id: orders[0].id,
      product_id: data.bowl.id,
      quantity: 1,
      unit_price: data.bowl.price
    });
    return orders[0];
  };

  const wantsMenu = ['hola', 'buenas', 'inicio', 'menu', 'menú', 'empezar', 'cancelar'].includes(text);

  if (wantsMenu || state === 'idle') {
    const products = await sb('GET', 'products?select=id,name,price,emoji&available=eq.true&order=name');
    data = { products: products.map(p => ({ id: p.id, name: p.name, price: Number(p.price), emoji: p.emoji })) };
    await saveState('choosing_bowl', data);
    reply = '¡Hola ' + pushName + '! 🍲 Soy *Mono*, el asistente de Monkey Food Fitness.\n\n' + menuText(data.products);
  } else if (state === 'choosing_bowl') {
    const idx = parseInt(text, 10);
    const products = data.products || [];
    if (idx >= 1 && idx <= products.length) {
      data.bowl = products[idx - 1];
      await saveState('choosing_delivery', data);
      reply = 'Elegiste: *' + data.bowl.name + '* - $' + data.bowl.price + ' ✅\n\n¿Cómo lo quieres?\n\n1️⃣ *Delivery* (te lo enviamos)\n2️⃣ *Retiro* (pasas a buscar)';
    } else {
      reply = 'No te entendí 🙈 Responde con el *número* del bowl (por ejemplo *1*), o escribe *menú* para verlo de nuevo.';
    }
  } else if (state === 'choosing_delivery') {
    if (text === '1') {
      await saveState('awaiting_address', data);
      reply = '¡Perfecto! 📍 Escríbenos tu *dirección completa* para la entrega.';
    } else if (text === '2') {
      await createOrder('Retiro en local', 'Retiro');
      await saveState('idle', {});
      reply = '✅ *Pedido confirmado*\n\n📋 ' + data.bowl.name + '\n📍 Retiro en local\n💰 Total: $' + data.bowl.price + '\n\nTe avisamos cuando esté listo. ¡Gracias! 🍲';
    } else {
      reply = 'Responde *1* para delivery o *2* para retiro 🙂';
    }
  } else if (state === 'awaiting_address') {
    await createOrder(rawText, 'Delivery');
    await saveState('idle', {});
    reply = '✅ *Pedido confirmado*\n\n📋 ' + data.bowl.name + '\n📍 Delivery a: ' + rawText + '\n💰 Total: $' + data.bowl.price + '\n\nTe contactamos para coordinar el pago. ¡Gracias! 🍲';
  } else {
    reply = 'Escribe *menú* para ver los bowls disponibles 🍲';
  }
} catch (error) {
  reply = 'Ups, tuvimos un problema técnico 🙈 Intenta de nuevo en un momento.';
}

return [{ json: { number: phone, reply } }];

// Send reply through Evolution API v2: POST /message/sendText/{instance} with flat { number, text }
const EVOLUTION_URL = $env.EVOLUTION_URL || 'http://evolution:8080';
const EVOLUTION_API_KEY = $env.EVOLUTION_API_KEY;
const INSTANCE = $env.EVOLUTION_INSTANCE || 'monkeyfood';

const { number, reply } = $json;

await this.helpers.httpRequest({
  method: 'POST',
  url: EVOLUTION_URL + '/message/sendText/' + INSTANCE,
  headers: {
    'apikey': EVOLUTION_API_KEY,
    'Content-Type': 'application/json'
  },
  body: JSON.stringify({ number, text: reply })
});

return [{ json: { success: true, number } }];
